"""Hand-written, bilingual descriptions that sit on top of the PSI records.

Everything here is a paraphrase of a named source: the study's `investigation.json`
card in PSI, its Experimental table, or the challenge statement. Numbers that can be
computed from the tables are NOT written here; the build computes them.
"""

from __future__ import annotations


def T(ru: str, en: str) -> dict:
    return {"ru": ru, "en": en}


CAMERAS = T("камеры, радиометры, фотоумножители, термопары, расходомеры и датчики давления",
            "cameras, radiometers, photomultiplier tubes, thermocouples, mass-flow controllers and pressure transducers")

# group   : shared hardware family (used by the comparison page)
# state   : physical state of the fuel
# pillars : NASA fire-safety pillars the study informs (prevention / detection / suppression) or "fundamentals"
# safety  : 3 = directly about crewed-habitat fire safety, 2 = supporting, 1 = fundamental combustion science
